using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Core.Asistente;

public sealed record SolicitudAuditoria(
    string IpOrigen,
    string CorrelationId,
    Rol? Rol,
    string? UsuarioId,
    string? Pregunta,
    ResultadoAuditoria Resultado,
    long DuracionMs);

public sealed class AuditorPeticiones
{
    public const int LongitudMaximaPregunta = 1000;
    public const string PreguntaNoEvaluada = "[NO_EVALUADA]";

    private readonly IAuditoria _auditoria;
    private readonly IReloj _reloj;
    private DirectorioAcademico? _personasConocidas;

    public AuditorPeticiones(IAuditoria auditoria, IReloj reloj)
    {
        _auditoria = auditoria;
        _reloj = reloj;
    }

    public DateTimeOffset AhoraUtc => _reloj.AhoraUtc;

    public static string SanearPregunta(Usuario usuario, string? pregunta, DirectorioAcademico directorio)
    {
        if (string.IsNullOrEmpty(pregunta))
        {
            return string.Empty;
        }

        return Limpiar(DetectorTerceros.EnmascararTerceros(usuario, pregunta, directorio));
    }

    public void RecordarPersonas(DirectorioAcademico directorio) => Volatile.Write(ref _personasConocidas, directorio);

    public string PreguntaSinIdentidad(string? pregunta)
    {
        var personas = Volatile.Read(ref _personasConocidas);
        return pregunta is null || personas is null
            ? PreguntaNoEvaluada
            : Limpiar(DetectorTerceros.EnmascararPersonas(pregunta, personas));
    }

    private static string Limpiar(string enmascarada)
    {
        var sinControl = new string([.. enmascarada.Select(caracter => char.IsControl(caracter) ? ' ' : caracter)]);
        return sinControl.Length > LongitudMaximaPregunta ? sinControl[..LongitudMaximaPregunta] : sinControl;
    }

    public void Registrar(EventoAuditoria evento) => _auditoria.Registrar(evento);

    public void RegistrarSinConsultas(SolicitudAuditoria solicitud)
    {
        _auditoria.Registrar(new EventoAuditoria(
            _reloj.AhoraUtc,
            solicitud.CorrelationId,
            solicitud.IpOrigen,
            solicitud.Rol,
            solicitud.UsuarioId,
            PreguntaSinIdentidad(solicitud.Pregunta),
            solicitud.Resultado,
            null,
            [],
            [],
            [],
            0,
            0m,
            solicitud.DuracionMs,
            false));
    }

    public void RegistrarMultiplesIdentidades(string ipOrigen, IReadOnlyList<string> usuarioIds) =>
        _auditoria.RegistrarMultiplesIdentidades(new EventoMultiplesIdentidades(_reloj.AhoraUtc, ipOrigen, usuarioIds));
}
namespace TutorFlow.Core.Asistente;

public sealed class PresupuestoDiario
{
    private readonly Lock _candado = new();
    private readonly IReloj _reloj;
    private readonly LimitesAsistente _limites;
    private DateOnly _dia;
    private decimal _gastado;
    private decimal _reservado;

    public PresupuestoDiario(IReloj reloj, LimitesAsistente limites)
    {
        _reloj = reloj;
        _limites = limites;
        _dia = DiaActual();
    }

    public bool TryReservar(decimal reservaUsd)
    {
        lock (_candado)
        {
            ReiniciarSiCambioElDia();
            var reserva = Math.Min(reservaUsd, _limites.PresupuestoDiarioUsd);
            if (_gastado + _reservado + reserva > _limites.PresupuestoDiarioUsd)
            {
                return false;
            }

            _reservado += reserva;
            return true;
        }
    }

    public void Sustituir(decimal reservaUsd, decimal costoRealUsd)
    {
        lock (_candado)
        {
            var reserva = Math.Min(reservaUsd, _limites.PresupuestoDiarioUsd);
            _reservado = Math.Max(0m, _reservado - reserva);
            ReiniciarSiCambioElDia();
            _gastado += costoRealUsd;
        }
    }

    private DateOnly DiaActual() => DateOnly.FromDateTime(_reloj.AhoraUtc.UtcDateTime);

    private void ReiniciarSiCambioElDia()
    {
        var hoy = DiaActual();
        if (hoy == _dia)
        {
            return;
        }

        _dia = hoy;
        _gastado = 0m;
    }
}
using System.Security.Cryptography;

namespace TutorFlow.Core.Asistente;

public sealed class ConfiguracionAsistente
{
    private const int BytesDelMarcadorAleatorio = 32;
    private const int TokensDeEntradaReservados = 8000;
    private const int TokensDeSalidaReservados = 2000;
    private const int MinimoPermitido = 1;

    public const int RelevanciaMinimaPorDefecto = 2;
    public const int ApoyoMinimoPorDefecto = 2;

    public ConfiguracionAsistente(
        PrecioModelo? precio,
        string? marcadorCanarioConfigurado,
        IReadOnlyCollection<string> codigosAsignatura,
        decimal? reservaPorPeticionUsd = null,
        int relevanciaMinima = RelevanciaMinimaPorDefecto,
        int apoyoMinimoRespaldo = ApoyoMinimoPorDefecto,
        IReadOnlyList<AsignaturaCatalogo>? catalogo = null)
    {
        Catalogo = catalogo is { Count: > 0 } ? catalogo : CatalogoAsignaturas.PorDefecto;
        Precio = precio;
        MarcadorCanario = string.IsNullOrWhiteSpace(marcadorCanarioConfigurado)
            ? Convert.ToHexString(RandomNumberGenerator.GetBytes(BytesDelMarcadorAleatorio))
            : marcadorCanarioConfigurado;
        CodigosAsignatura = codigosAsignatura;
        ReservaPorPeticionUsd = reservaPorPeticionUsd ?? ReservaPorDefecto(precio);
        RelevanciaMinima = Math.Max(MinimoPermitido, relevanciaMinima);
        ApoyoMinimoRespaldo = Math.Max(MinimoPermitido, apoyoMinimoRespaldo);
    }

    public PrecioModelo? Precio { get; }

    public string MarcadorCanario { get; }

    public IReadOnlyCollection<string> CodigosAsignatura { get; }

    public IReadOnlyList<AsignaturaCatalogo> Catalogo { get; }

    public decimal ReservaPorPeticionUsd { get; }

    public int RelevanciaMinima { get; }

    public int ApoyoMinimoRespaldo { get; }

    private static decimal ReservaPorDefecto(PrecioModelo? precio) =>
        CalculadoraCosto.Calcular(new UsoTokens(TokensDeEntradaReservados, TokensDeSalidaReservados), precio);
}
namespace TutorFlow.Core.Asistente;

public sealed class LimitesAsistente
{
    public int MaximoCaracteresPregunta { get; init; } = 1000;
    public int MaximoBytesCuerpo { get; init; } = 16 * 1024;
    public int PreguntasPorMinutoPorIp { get; init; } = 60;
    public int MaximoSeccionesRecuperadas { get; init; } = 6;
    public int MaximoTokensSalida { get; init; } = 2000;
    public int MaximoInvocacionesHerramientas { get; init; } = 4;
    public int TimeoutLlmSegundos { get; init; } = 20;
    public int PresupuestoApiAcademicaSegundos { get; init; } = 6;
    public decimal PresupuestoDiarioUsd { get; init; } = 5m;
    public int MaximoIdentidadesPorIp { get; init; } = 3;
    public int VentanaIdentidadesMinutos { get; init; } = 10;
    public bool BloquearMultiplesIdentidades { get; init; }
}

