    private readonly OrdenDeReglasPorRelevancia _ordenDeReglas;
    private readonly AfirmacionesDePerdida _afirmacionesDePerdida;

    public PreguntarAsistente(
        IApiAcademica apiAcademica,
        IClienteLlm clienteLlm,
