using System.Text.Json;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api.Tests.Operacion;

public sealed class AuditoriaApiTests
{
    private const string IpDeLaPrueba = "10.1.2.3";
    private static readonly JsonSerializerOptions SinEscapes = new() { Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping };
    private static readonly string[] ValoresDeNotas = ["4.39", "4.5", "4.8", "4.1", "4.0", "3.8", "2.6", "0.0"];

    public static TheoryData<string, string, string, ResultadoAuditoria, string> UnEventoPorPregunta => new()
    {
        { "estudiante", "EST-001", "¿Cuál es mi promedio ponderado del periodo?", ResultadoAuditoria.Respondida, "EST-001" },
        { "estudiante", "EST-001", "¿Qué dice el reglamento sobre parqueaderos?", ResultadoAuditoria.SinInformacion, string.Empty },
        { "estudiante", "EST-001", "¿Cuál es la nota de Bases de Datos de Andrés Martínez?", ResultadoAuditoria.Denegada, string.Empty },
        { "coordinador", "COORD-02", "¿Qué estudiantes de mi programa tienen materias perdidas?", ResultadoAuditoria.Respondida, "EST-004,EST-005,EST-006" }
    };

    private static ClienteLlmDoble LlmPara(ResultadoAuditoria resultado) => resultado switch
    {
        ResultadoAuditoria.SinInformacion => ClienteLlmDoble.Texto(Textos.SinInformacion),
        ResultadoAuditoria.Respondida => ClienteLlmDoble.ConsultaDatos(redactar: _ => "Resumen de tus datos académicos."),
        _ => ClienteLlmDoble.Texto("Respuesta de prueba.")
    };

    [Theory]
    [MemberData(nameof(UnEventoPorPregunta))]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-113")]
    public async Task Cada_pregunta_emite_exactamente_un_evento_con_resultado_y_consultados(string rol, string id, string pregunta, ResultadoAuditoria resultado, string consultados)
    {
        using var fabrica = new FabricaApi(llm: LlmPara(resultado));

        await fabrica.PreguntarAsync(rol, id, pregunta, IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(resultado, evento.Resultado);
        Assert.Equal(consultados.Length == 0 ? [] : consultados.Split(','), evento.EstudiantesConsultados.Order().ToArray());
        var serializado = JsonSerializer.Serialize(evento, SinEscapes);
        Assert.All(ValoresDeNotas, valor => Assert.DoesNotContain($"\"{valor}\"", serializado, StringComparison.Ordinal));
        Assert.DoesNotContain("Resumen de tus datos", serializado, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-113")]
    public async Task ESC_113_Una_pregunta_invalida_emite_un_evento_invalida()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "   ", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(ResultadoAuditoria.Invalida, evento.Resultado);
        Assert.Equal(IpDeLaPrueba, evento.IpOrigen);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-113")]
    public async Task ESC_113_Un_cuerpo_demasiado_grande_emite_un_evento_invalida()
    {
        using var fabrica = new FabricaApi();
        var cuerpo = $$"""{"pregunta":"hola","usuario":{"rol":"estudiante","id":"EST-001"},"relleno":"{{new string('x', 17 * 1024)}}"}""";

        await fabrica.EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", cuerpo, IpDeLaPrueba);

        Assert.Equal(ResultadoAuditoria.Invalida, Assert.Single(fabrica.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-114")]
    public async Task ESC_114_El_evento_registra_ids_y_recursos_pero_no_valores_de_notas()
    {
        using var fabrica = new FabricaApi(llm: ClienteLlmDoble.ConsultaDatos());

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es mi promedio ponderado del periodo?", IpDeLaPrueba);

        Assert.Contains("4.39", respuesta.Respuesta, StringComparison.Ordinal);
        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Equal(["EST-001"], evento.EstudiantesConsultados.ToArray());
        Assert.Contains(RecursoConsultado.Notas, evento.RecursosConsultados);
        var serializado = JsonSerializer.Serialize(evento, SinEscapes);
        Assert.All(ValoresDeNotas, valor => Assert.DoesNotContain($"\"{valor}\"", serializado, StringComparison.Ordinal));
        Assert.DoesNotContain("Cálculo Integral", serializado, StringComparison.Ordinal);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-118")]
    public async Task ESC_118_Los_terceros_se_enmascaran_en_la_pregunta_auditada_y_la_ip_esta_presente()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es la nota de Bases de Datos de Andrés Martínez?", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Contains("[TERCERO]", evento.Pregunta, StringComparison.Ordinal);
        Assert.DoesNotContain("Andrés Martínez", evento.Pregunta, StringComparison.Ordinal);
        Assert.DoesNotContain("Martinez", evento.Pregunta, StringComparison.OrdinalIgnoreCase);
        Assert.Equal(IpDeLaPrueba, evento.IpOrigen);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-118")]
    public async Task Los_ids_de_terceros_tambien_se_enmascaran_en_la_pregunta_auditada()
    {
        using var fabrica = new FabricaApi();

        await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuáles son las notas de EST-002?", IpDeLaPrueba);

        var evento = Assert.Single(fabrica.Auditoria.Eventos);
        Assert.Contains("[TERCERO]", evento.Pregunta, StringComparison.Ordinal);
        Assert.DoesNotContain("EST-002", evento.Pregunta, StringComparison.Ordinal);
using System.Text.Json;
using System.Text.RegularExpressions;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Dobles;

public delegate RespuestaLlm GuionLlm(SolicitudLlm solicitud, int numeroLlamada);

public sealed partial class ClienteLlmDoble : IClienteLlm
{
    public const string ParametroEstudianteId = "estudianteId";
    public static readonly UsoTokens UsoPorDefecto = new(100, 20);

    private readonly GuionLlm _guion;
    private readonly List<SolicitudLlm> _solicitudes = [];
    private readonly Lock _candado = new();

    public ClienteLlmDoble(GuionLlm guion)
    {
        _guion = guion;
    }

    public int Llamadas
    {
        get
        {
            lock (_candado)
            {
                return _solicitudes.Count;
            }
        }
    }

    public IReadOnlyList<SolicitudLlm> Solicitudes
    {
        get
        {
            lock (_candado)
            {
                return [.. _solicitudes];
            }
        }
    }

    public static ClienteLlmDoble Texto(string texto, UsoTokens? uso = null) =>
        new((_, _) => new RespuestaLlm(texto, [], uso ?? UsoPorDefecto, false));

    public static ClienteLlmDoble Rechaza() =>
        new((_, _) => new RespuestaLlm(null, [], UsoPorDefecto, true));

    public static ClienteLlmDoble Falla(Exception excepcion) =>
        new((_, _) => throw excepcion);

    public static ClienteLlmDoble QueNuncaResponde() =>
        new((_, _) => throw new TaskCanceledException("llm sin respuesta"));

    public static ClienteLlmDoble ConsultaDatos(string? estudianteIdParaCoordinador = null, Func<SolicitudLlm, string>? redactar = null, UsoTokens? uso = null)
    {
        var redactor = redactar ?? EcoDeHerramientas;
        var consumo = uso ?? UsoPorDefecto;
        return new ClienteLlmDoble((solicitud, n) => ConsultarOResponder(solicitud, n, estudianteIdParaCoordinador, redactor, consumo));
    }

    private static RespuestaLlm ConsultarOResponder(SolicitudLlm solicitud, int numero, string? estudianteId, Func<SolicitudLlm, string> redactor, UsoTokens consumo)
    {
        var llamadas = numero == 0 ? LlamarTodas(solicitud.Herramientas, estudianteId) : [];
        return llamadas.Count > 0
            ? new RespuestaLlm(null, llamadas, consumo, false)
            : new RespuestaLlm(redactor(solicitud), [], consumo, false);
    }

    public static ClienteLlmDoble PideEstudiante(string estudianteId, UsoTokens? uso = null) =>
        new((solicitud, n) =>
        {
            var herramienta = ElegirHerramienta(solicitud.Herramientas);
            return n == 0 && herramienta is not null
                ? new RespuestaLlm(null, [Llamada("pide-1", herramienta.Nombre, JsonSerializer.Serialize(new Dictionary<string, string> { [ParametroEstudianteId] = estudianteId }))], uso ?? UsoPorDefecto, false)
                : new RespuestaLlm("Sin datos", [], uso ?? UsoPorDefecto, false);
        });

    public static ClienteLlmDoble PideHerramientaSinParar() =>
        new((solicitud, n) => new RespuestaLlm(null, [Llamada($"sin-parar-{n}", solicitud.Herramientas[0].Nombre, "{}")], UsoPorDefecto, false));

    public static ClienteLlmDoble PideHerramientaVariasVecesEnUnaRespuesta(int veces) =>
        new((solicitud, _) => new RespuestaLlm(
            null,
            Enumerable.Range(0, veces).Select(i => Llamada($"lote-{i}", solicitud.Herramientas[0].Nombre, "{}")).ToList(),
            UsoPorDefecto,
            false));

    public static IReadOnlyList<string> ParametrosDeId(SolicitudLlm solicitud) =>
        solicitud.Herramientas
            .SelectMany(h => h.Parametros)
            .Select(p => p.Nombre)
            .Where(n => ParametroDeIdRegex().IsMatch(n))
            .ToList();

    public static string EcoDeHerramientas(SolicitudLlm solicitud) =>
        string.Join("\n", solicitud.Mensajes.Where(m => m.Rol == RolMensaje.Herramienta).Select(m => m.Contenido));

    public Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
    {
        int numero;
        lock (_candado)
        {
            numero = _solicitudes.Count;
            _solicitudes.Add(solicitud);
        }

        return Task.FromResult(_guion(solicitud, numero));
    }

    private static List<LlamadaHerramienta> LlamarTodas(IReadOnlyList<HerramientaLlm> herramientas, string? estudianteId) =>
        herramientas
            .Where(h => estudianteId is not null || !h.Parametros.Any(p => p.Nombre == ParametroEstudianteId))
            .Select(h => Llamada($"llamada-{h.Nombre}", h.Nombre, ArgumentosPara(h, estudianteId)))
            .ToList();

    private static string ArgumentosPara(HerramientaLlm herramienta, string? estudianteId) =>
        herramienta.Parametros.Any(p => p.Nombre == ParametroEstudianteId)
            ? $$"""{"{{ParametroEstudianteId}}":"{{estudianteId}}"}"""
            : "{}";

    private static HerramientaLlm? ElegirHerramienta(IReadOnlyList<HerramientaLlm> herramientas) =>
        herramientas.FirstOrDefault(h => h.Parametros.Any(p => p.Nombre == ParametroEstudianteId)) ?? (herramientas.Count > 0 ? herramientas[0] : null);

    private static LlamadaHerramienta Llamada(string id, string nombre, string argumentosJson) => new(id, nombre, argumentosJson);

    [GeneratedRegex("id$|estudiante|usuario|alumno", RegexOptions.IgnoreCase)]
    private static partial Regex ParametroDeIdRegex();
}
using System.Collections.Concurrent;
using System.Net;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Api.Tests.Dobles;

public sealed class AuditoriaEnMemoria : IAuditoria
{
    private readonly ConcurrentQueue<EventoAuditoria> _eventos = new();
    private readonly ConcurrentQueue<EventoMultiplesIdentidades> _multiples = new();

    public IReadOnlyList<EventoAuditoria> Eventos => [.. _eventos];

    public IReadOnlyList<EventoMultiplesIdentidades> MultiplesIdentidades => [.. _multiples];

    public void Registrar(EventoAuditoria evento) => _eventos.Enqueue(evento);

    public void RegistrarMultiplesIdentidades(EventoMultiplesIdentidades evento) => _multiples.Enqueue(evento);
}

public sealed class RelojControlado : IReloj
{
    private DateTimeOffset _ahora = new(2026, 11, 22, 12, 0, 0, TimeSpan.Zero);

    public DateTimeOffset AhoraUtc => _ahora;

    public void Fijar(DateTimeOffset instante) => _ahora = instante;

    public void Avanzar(TimeSpan intervalo) => _ahora += intervalo;
}

public sealed class CapturaLogs : ILoggerProvider
{
    private readonly ConcurrentQueue<string> _mensajes = new();

    public IReadOnlyList<string> Mensajes => [.. _mensajes];

    public ILogger CreateLogger(string categoryName) => new Registro(_mensajes);

    public void Dispose()
    {
    }

    private sealed class Registro(ConcurrentQueue<string> destino) : ILogger
    {
        public IDisposable? BeginScope<TState>(TState state)
            where TState : notnull => null;

        public bool IsEnabled(LogLevel logLevel) => true;

        public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception? exception, Func<TState, Exception?, string> formatter)
        {
            destino.Enqueue(formatter(state, exception) + exception);
        }
    }
}

public sealed class FiltroIpRemota : IStartupFilter
{
    public const string Encabezado = "X-Test-Ip";

    public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next) =>
        app =>
        {
            app.Use(async (contexto, siguiente) =>
            {
                if (contexto.Request.Headers.TryGetValue(Encabezado, out var ip) && IPAddress.TryParse(ip.ToString(), out var direccion))
                {
                    contexto.Connection.RemoteIpAddress = direccion;
                }

                await siguiente();
            });
            next(app);
        };
}

