    {
        { [Art3.ToString()], "El reglamento_academico_2023.md fue derogado (reglamento_academico_2025.md · Artículo 3).", "El reglamento_academico_2023.md fue derogado (reglamento_academico_2025.md · Artículo 3)." },
        { [Art3.ToString()], "Ya no aplica reglamento_academico_2023.md · Artículo 9.", "Ya no aplica." },
        { [Sec3.ToString()], "La definitiva se calcula según evaluacion_y_calificaciones.md · Secciones 3 y 5.", "La definitiva se calcula." },
